/*
 * MOD (memreclaim): NPC models without the animations they never play.
 *
 * An NPC model (loadMMD class 0) is read whole into a malloc3 block: TMD,
 * animation table and every animation, although an NPC only ever plays a
 * few of them (the partner's care animations take a third of most MMDs).
 * Right after the read, trimNpcModel keeps the slots NPC_ANIM_KEEP_* mark for
 * the type (src/main/npc_anim_keep.c, generated by tools/npcanims.py: map
 * AI, battle, the scripts' animations on that type), points every other
 * slot to a one-frame stub (the idle's first pose), packs the kept
 * animations and gives the rest of the block back to the heap.
 *
 * - The stub instead of 0: startAnimation ignores a 0 slot and the previous
 *   animation goes on, so a scene that waits for an animation the audit
 *   missed would wait forever; with the stub the NPC holds still one frame
 *   and the scene goes on.
 * - The packed model is moved to the top of its block and the bottom is
 *   freed: malloc3 carves blocks from the top of a free block, so the freed
 *   part joins the free block below it instead of leaving a hole.
 * - Runs before GsMapModelingData (the TMD is still in file form) and only
 *   for types below NUM_NPC_ANIM_TYPES; partner and tamer models (fixed
 *   buffers) are never touched.
 */
#include <dw/params.h>
#include <dw/types.h>

#define NUM_NPC_ANIM_TYPES	180
#define MAX_ANIM_SLOTS		64

typedef struct {
	int32_t models;		/* NPC models trimmed */
	int32_t bytes;		/* heap bytes given back, all loads */
	int32_t last;		/* ... by the last one */
} NpcTrimStats;

extern const uint32_t NPC_ANIM_KEEP_MASKS[][2];
extern const uint8_t NPC_ANIM_KEEP_INDEX[NUM_NPC_ANIM_TYPES];
NpcTrimStats MOD_NPC_TRIM_STATS;
int32_t MOD_NPC_STUB_HITS;	/* startAnimation landed on a stub (should stay 0) */
int32_t MOD_NPC_STUB_LAST;	/* (type << 8) | slot of the last one */

void free3(void *ptr);

static void copyDown16(uint16_t *dst, uint16_t *src, int32_t n)
{
	while (n-- > 0) {
		*dst++ = *src++;
	}
}

static void copyUp32(uint32_t *dst, uint32_t *src, int32_t n)
{
	while (n-- > 0) {
		dst[n] = src[n];
	}
}

/* Gives back the bottom of the malloc3 block at mmd beyond `size` bytes. */
static uint8_t *shrinkBlock(uint8_t *mmd, int32_t size)
{
	uint32_t *hdr = (uint32_t *)mmd - 2;
	int32_t units = hdr[1];
	int32_t need = (size + 7) & ~7;
	int32_t spare = ((units - 1) * 8 - need) & ~7;
	uint8_t *base;

	if (spare < 16) {
		return mmd;
	}
	base = mmd + spare;
	copyUp32((uint32_t *)base, (uint32_t *)mmd, need / 4);
	((uint32_t *)base)[-2] = 0;
	((uint32_t *)base)[-1] = units - spare / 8;
	hdr[0] = 0;
	hdr[1] = spare / 8;
	free3(mmd);
	MOD_NPC_TRIM_STATS.models++;
	MOD_NPC_TRIM_STATS.bytes += spare;
	MOD_NPC_TRIM_STATS.last = spare;
	return base;
}

/*
 * mmd: a just-read NPC model of `size` bytes in its malloc3 block. Returns
 * where the model is now (the block may have moved up).
 */
uint8_t *trimNpcModel(int32_t type, uint8_t *mmd, int32_t size)
{
	uint32_t starts[MAX_ANIM_SLOTS];
	uint32_t newOff[MAX_ANIM_SLOTS];
	int8_t kept[MAX_ANIM_SLOTS];
	uint32_t *tab;
	uint32_t animBytes;
	uint32_t first = 0;
	uint32_t o;
	uint32_t len;
	uint32_t pos;
	uint32_t dropped = 0;
	int32_t n;
	int32_t ns = 0;
	int32_t i;
	int32_t j;
	int32_t k;
	int32_t isKept;
	int32_t poseWords;
	int32_t stubBytes;
	int16_t *anim0;
	int16_t *stub;

	if ((type < 0) || (type >= NUM_NPC_ANIM_TYPES)) {
		return mmd;
	}
	tab = (uint32_t *)(mmd + ((uint32_t *)mmd)[1]);
	animBytes = size - ((uint32_t *)mmd)[1];

	/* the table has (smallest offset) / 4 slots */
	for (i = 0; (i < MAX_ANIM_SLOTS) && ((first == 0) || (4 * (uint32_t)i < first)); i++) {
		if ((tab[i] != 0) && ((first == 0) || (tab[i] < first))) {
			first = tab[i];
		}
	}
	n = first / 4;
	if ((first == 0) || (n > MAX_ANIM_SLOTS) || (tab[0] == 0)) {
		return mmd;
	}

	/* distinct animations in file order; kept if any slot that uses it is */
	for (i = 0; i < n; i++) {
		o = tab[i];
		if (o == 0) {
			continue;
		}
		isKept = (NPC_ANIM_KEEP_MASKS[NPC_ANIM_KEEP_INDEX[type]][i >> 5] >> (i & 31)) & 1;
		for (j = 0; (j < ns) && (starts[j] != o); j++);
		if (j == ns) {
			for (k = ns++; (k > 0) && (starts[k - 1] > o); k--) {
				starts[k] = starts[k - 1];
				kept[k] = kept[k - 1];
			}
			starts[k] = o;
			kept[k] = isKept;
		} else if (isKept) {
			kept[j] = 1;
		}
	}
	for (j = 0; j < ns; j++) {
		if (!kept[j]) {
			dropped += ((j + 1 < ns) ? starts[j + 1] : animBytes) - starts[j];
		}
	}

	/* the stub: frame count 1, slot 0's first pose, end */
	anim0 = (int16_t *)((uint8_t *)tab + tab[0]);
	poseWords = (DIGIMON_DATA[type].boneCount - 1) * ((anim0[0] & 0x8000) ? 9 : 6);
	stubBytes = (poseWords + 2) * 2;
	if (dropped < (uint32_t)stubBytes + 16) {
		return mmd;
	}

	/* pack the kept animations down, in file order (each only moves down) */
	pos = first;
	for (j = 0; j < ns; j++) {
		len = ((j + 1 < ns) ? starts[j + 1] : animBytes) - starts[j];
		if (kept[j]) {
			newOff[j] = pos;
			if (pos != starts[j]) {
				copyDown16((uint16_t *)((uint8_t *)tab + pos),
					   (uint16_t *)((uint8_t *)tab + starts[j]), len / 2);
			}
			pos += len;
		}
	}
	for (i = 0; i < n; i++) {
		if (tab[i] == 0) {
			continue;
		}
		for (j = 0; starts[j] != tab[i]; j++);
		tab[i] = kept[j] ? newOff[j] : pos;
	}
	anim0 = (int16_t *)((uint8_t *)tab + tab[0]);
	stub = (int16_t *)((uint8_t *)tab + pos);
	stub[0] = (anim0[0] & 0x8000) | 1;
	copyDown16((uint16_t *)&stub[1], (uint16_t *)&anim0[1], poseWords);
	stub[poseWords + 1] = 0;
	pos += stubBytes;

	return shrinkBlock(mmd, ((uint8_t *)tab - mmd) + pos);
}
